<?php
namespace App\Jobs;
use App\Models\Booking; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Cache;
class RefundEventBookingsJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=5; public array $backoff=[20,60,180,600]; public function __construct(public int $eventId){} public function handle():void{Booking::where('event_id',$this->eventId)->where('status','paid')->orderBy('id')->chunkById(300,function($rows){foreach($rows as $candidate){$refunded=DB::transaction(function()use($candidate){$b=Booking::with('items')->whereKey($candidate->id)->lockForUpdate()->first();if(!$b||$b->status->value!=='paid')return false;foreach($b->items as $item){$cat=\App\Models\TicketCategory::whereKey($item->ticket_category_id)->lockForUpdate()->first();if($cat)$cat->update(['sold'=>max(0,$cat->sold-$item->quantity)]);}$b->update(['status'=>'refunded']);return true;});if($refunded)EventCancellationNoticeJob::dispatch($candidate->id)->onQueue('critical');}});Cache::tags(['events'])->flush();}}
